using Amazon.DynamoDBv2;
using Amazon.DynamoDBv2.Model;

var dynamoDb = new AmazonDynamoDBClient(RegionEndpoint.USEast1);

// Create
var putItem = new PutItemRequest
{
    TableName = "Posts",
    Item = new Dictionary<string, AttributeValue>
    {
        { "Id", new AttributeValue { S = Guid.NewGuid().ToString() } },
        { "Title", new AttributeValue { S = "Getting Started with DynamoDB" } },
        { "Content", new AttributeValue { S = "DynamoDB is a NoSQL database..." } },
        { "PublishedAt", new AttributeValue { N = DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString() } }
    }
};
await dynamoDb.PutItemAsync(putItem);

// Read
var getItem = new GetItemRequest
{
    TableName = "Posts",
    Key = new Dictionary<string, AttributeValue>
    {
        { "Id", new AttributeValue { S = "the-post-id" } }
    }
};
var getResponse = await dynamoDb.GetItemAsync(getItem);

// Delete
var deleteItem = new DeleteItemRequest
{
    TableName = "Posts",
    Key = new Dictionary<string, AttributeValue>
    {
        { "Id", new AttributeValue { S = "the-post-id" } }
    }
};
await dynamoDb.DeleteItemAsync(deleteItem);

var query = new QueryRequest
{
    TableName = "Posts",
    KeyConditionExpression = "Id = :id",
    ExpressionAttributeValues = new Dictionary<string, AttributeValue>
    {
        { ":id", new AttributeValue { S = "the-post-id" } }
    }
};

var queryResponse = await dynamoDb.QueryAsync(query);
foreach (var item in queryResponse.Items)
{
    Console.WriteLine($"Title: {item["Title"].S}");
}
